var t=[{title:`Hoe complex een oefening is`,text:`Een ondersteunde machine-row beweegt langs een stabiel pad. Een Romanian deadlift op één been vraagt balans, rompcontrole en heupcoördinatie, en een kettlebellswing voegt snelheid en timing toe. Je kunt heel sterk zijn en toch nieuw in een van deze vaardigheden.`},{title:`Ga van voorspelbaar naar uitdagend`,text:`Begin met stabiele posities en langzamere herhalingen en leer één nieuwe vaardigheid tegelijk. Maak de oefening dan zwaarder door steun weg te nemen, de hefboom te veranderen, het bereik te vergroten of beheerste snelheid toe te voegen. Een opbouw moet het doel van de beweging behouden en vermijden dat je alle eisen tegelijk verandert.`},{title:`Vermoeidheid verandert coördinatie`,text:`Een oefening die je vroeg in een training goed deed, kan na veel herhalingen wankel worden. Doe oefeningen met veel vaardigheid eerder, rust langer als dat nodig is en beëindig een set wanneer je balans of controle wegvalt. Complexe ballistische oefeningen zijn meestal een slechte eerste keuze voor een vermoeide beginner.`},{title:`Voorbeeld`,text:`Leer je lunges, dan kun je beginnen met split squats terwijl je een leuning vasthoudt, doorgaan naar reverse lunges zonder steun en later wandelende lunges proberen. Een snellere variant is niet automatisch beter.`},{title:`TrainUp gebruiken`,text:`Als TrainUp je schema opbouwt, kiest het oefeningen die passen bij je niveau en coördinatie, evenals je beperkingen en uitrusting.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Praktische richtlijnen van het ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};